/* The supplied reference is embedded below during packaging. Keeping the fixed
   artwork from that reference preserves its exact logo, lettering, texture,
   ornamentation and colours. No third-party images or fonts are used. */
const REFERENCE_IMAGE = 'data:image/png;base64,';

(() => {
  'use strict';
  const WIDTH = 1198, HEIGHT = 1313, EXPORT_SCALE = 3;
  const defaults = Object.freeze({ name: 'Bonolo Makola', dob: '2021-08-18', gender: 'Male' });
  const photoBox = Object.freeze({ x: 319, y: 394, w: 557, h: 635 });
  const $ = id => document.getElementById(id);
  const form = $('student-form'), card = $('graduation-card'), stage = $('poster-stage');
  const fields = { name: $('student-name'), dob: $('student-dob'), gender: $('student-gender') };
  const labels = { name: $('name-label'), dob: $('dob-label'), gender: $('gender-label') };
  const photoControls = { x: $('photo-x'), y: $('photo-y'), zoom: $('photo-zoom') };
  const measureContext = document.createElement('canvas').getContext('2d');
  let sourceImage, artworkImage, originalPortrait, portraitImage, ready = false;
  let uploadRevision = 0, dragStart = null;
  const defaultTextCrops = {};
  const textBoxes = {
    name: { x: 316, y: 1047, w: 566, h: 74 },
    dob: { x: 390, y: 1140, w: 185, h: 39 },
    gender: { x: 688, y: 1140, w: 195, h: 39 }
  };

  function status(message, isError = false) {
    $('status').textContent = message;
    $('status').classList.toggle('error', isError);
  }

  function loadImage(src) {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error('The image could not be opened. Please use a JPG, PNG or WebP photo.'));
      img.src = src;
    });
  }

  function makeCanvas(w, h) {
    const canvas = document.createElement('canvas');
    canvas.width = w; canvas.height = h;
    return canvas;
  }

  function cropReference(box) {
    const canvas = makeCanvas(box.w, box.h);
    canvas.getContext('2d').drawImage(sourceImage, box.x, box.y, box.w, box.h, 0, 0, box.w, box.h);
    return canvas.toDataURL('image/png');
  }

  // Concave corner cut-outs traced from the inner edge of the original frame.
  // This path is identical to the objectBoundingBox clip-path used by CSS.
  function portraitPath() {
    return new Path2D('M 34 0 H 523 C 529 19 540 29 557 34 V 601 C 540 606 529 618 523 635 H 34 C 28 618 17 606 0 601 V 34 C 17 29 28 19 34 0 Z');
  }

  function prepareArtwork() {
    const canvas = makeCanvas(WIDTH, HEIGHT);
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    ctx.drawImage(sourceImage, 0, 0);
    const original = ctx.getImageData(0, 0, WIDTH, HEIGHT);
    const cleaned = ctx.getImageData(0, 0, WIDTH, HEIGHT);
    const pixel = (x, y, c) => original.data[(y * WIDTH + x) * 4 + c];

    // Replace only the variable lettering with nearby original ribbon/paper
    // colour. Every fixed decorative element stays untouched. The original
    // default text is stored separately, preserving its exact appearance.
    function clearLettering(x, y, w, h, mode) {
      for (let yy = y; yy < y + h; yy++) {
        for (let xx = x; xx < x + w; xx++) {
          const index = (yy * WIDTH + xx) * 4;
          for (let c = 0; c < 3; c++) {
            let colour;
            if (mode === 'ribbon') {
              const t = (xx - x) / w;
              let left = 0, right = 0;
              for (let k = 0; k < 12; k++) {
                left += pixel(343 + k, yy, c);
                right += pixel(842 + k, yy, c);
              }
              colour = (left / 12) * (1 - t) + (right / 12) * t;
              // Keep the source texture instead of a visibly flat rectangle.
              colour += (pixel(331 + (xx % 20), yy, c) - left / 12) * .3;
            } else {
              const t = (yy - y) / h;
              colour = pixel(xx, y - 6, c) * (1 - t) + pixel(xx, y + h + 6, c) * t;
            }
            const feather = Math.min(1, (xx - x + 1) / 4, (x + w - xx) / 4, (yy - y + 1) / 4, (y + h - yy) / 4);
            cleaned.data[index + c] = Math.round(colour * feather + original.data[index + c] * (1 - feather));
          }
        }
      }
    }
    clearLettering(369, 1050, 459, 62, 'ribbon');
    clearLettering(388, 1144, 182, 30, 'paper');
    clearLettering(686, 1144, 151, 30, 'paper');
    ctx.putImageData(cleaned, 0, 0);
    ctx.save(); ctx.translate(photoBox.x, photoBox.y); ctx.clip(portraitPath());
    ctx.fillStyle = '#fcfaf0'; ctx.fillRect(0, 0, photoBox.w, photoBox.h); ctx.restore();
    return canvas.toDataURL('image/png');
  }

  function displayDob(value) {
    if (!value) return '';
    const parts = value.split('-');
    return parts.length === 3 ? `${parts[2]}-${parts[1]}-${parts[0]}` : value;
  }

  function currentText() {
    return { name: fields.name.value, dob: `DOB: ${displayDob(fields.dob.value)}`, gender: `Gender: ${fields.gender.value}` };
  }

  function isDefault(key) { return fields[key].value === defaults[key]; }

  function fontFor(key, text) {
    const base = key === 'name' ? 68 : 26;
    const weight = key === 'name' ? '700' : '400';
    measureContext.font = `${weight} ${base}px "Times New Roman", Times, serif`;
    const maxWidth = key === 'name' ? 526 : textBoxes[key].w;
    const width = measureContext.measureText(text).width;
    const size = width > maxWidth ? base * maxWidth / width : base;
    return { size, weight, font: `${weight} ${size}px "Times New Roman", Times, serif` };
  }

  function updateText() {
    const text = currentText();
    for (const key of Object.keys(labels)) {
      const label = labels[key];
      label.textContent = text[key];
      label.style.fontSize = `${fontFor(key, text[key]).size}px`;
      // The original sample lettering is kept as a separate replaceable layer.
      // Other values are real HTML text in a matching classic serif typeface.
      label.style.backgroundImage = isDefault(key) && ready ? `url("${defaultTextCrops[key].src}")` : 'none';
      label.style.color = isDefault(key) && ready ? 'transparent' : key === 'name' ? '#fffdf4' : '#002d1c';
      label.style.textShadow = key === 'name' && !isDefault(key) ? '1px 2px 2px #002918' : 'none';
    }
    const name = fields.name.value || 'student';
    card.setAttribute('aria-label', `Dream Big Crèche graduation keepsake for ${name}`);
    $('student-portrait').alt = `${name}'s graduation portrait`;
  }

  function updatePhoto() {
    const img = $('student-portrait');
    img.style.setProperty('--photo-x', `${photoControls.x.value}%`);
    img.style.setProperty('--photo-y', `${photoControls.y.value}%`);
    img.style.setProperty('--photo-zoom', Number(photoControls.zoom.value) / 100);
  }

  function resetPhotoPosition() {
    photoControls.x.value = '50'; photoControls.y.value = '50'; photoControls.zoom.value = '100'; updatePhoto();
  }

  function fitStage() { card.style.setProperty('--poster-scale', stage.clientWidth / WIDTH); }

  function drawPortrait(ctx) {
    const { x, y, w, h } = photoBox;
    const zoom = Number(photoControls.zoom.value) / 100;
    const px = Number(photoControls.x.value) / 100, py = Number(photoControls.y.value) / 100;
    const cover = Math.max(w / portraitImage.naturalWidth, h / portraitImage.naturalHeight) * zoom;
    const dw = portraitImage.naturalWidth * cover, dh = portraitImage.naturalHeight * cover;
    ctx.save(); ctx.translate(x, y); ctx.clip(portraitPath());
    ctx.drawImage(portraitImage, (w - dw) * px, (h - dh) * py, dw, dh); ctx.restore();
  }

  async function renderPoster(scale) {
    if (!ready) throw new Error('The keepsake is still loading.');
    await document.fonts.ready;
    const canvas = makeCanvas(WIDTH * scale, HEIGHT * scale);
    const ctx = canvas.getContext('2d');
    ctx.scale(scale, scale); ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';
    ctx.drawImage(artworkImage, 0, 0, WIDTH, HEIGHT);
    drawPortrait(ctx);
    const text = currentText();
    for (const key of Object.keys(labels)) {
      const box = textBoxes[key];
      if (isDefault(key)) { ctx.drawImage(defaultTextCrops[key], box.x, box.y, box.w, box.h); continue; }
      ctx.save();
      ctx.beginPath(); ctx.rect(box.x, box.y, box.w, box.h); ctx.clip();
      ctx.font = fontFor(key, text[key]).font;
      ctx.fillStyle = key === 'name' ? '#fffdf4' : '#002d1c';
      ctx.textAlign = key === 'name' ? 'center' : 'left'; ctx.textBaseline = 'alphabetic';
      if (key === 'name') { ctx.shadowColor = '#002918'; ctx.shadowOffsetX = 1; ctx.shadowOffsetY = 2; ctx.shadowBlur = 2; }
      // Match the browser's actual font metrics and line-box centring.
      const fontMetrics = ctx.measureText('Hg');
      const ascent = fontMetrics.fontBoundingBoxAscent ?? fontMetrics.actualBoundingBoxAscent;
      const descent = fontMetrics.fontBoundingBoxDescent ?? fontMetrics.actualBoundingBoxDescent;
      const baseline = box.y + box.h / 2 + (ascent - descent) / 2;
      ctx.fillText(text[key], key === 'name' ? WIDTH / 2 : box.x, baseline);
      ctx.restore();
    }
    return canvas;
  }

  function pngBlob(canvas) {
    return new Promise((resolve, reject) => canvas.toBlob(blob => blob ? resolve(blob) : reject(new Error('PNG export failed. Please try again.')), 'image/png'));
  }

  function filename() {
    const name = fields.name.value.trim().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '') || 'Student';
    return `${name}-Dream-Big-Graduation.png`;
  }

  $('download').addEventListener('click', async () => {
    if (!form.reportValidity()) return;
    $('download').disabled = true; status('Preparing your high-resolution PNG…');
    try {
      const canvas = await renderPoster(EXPORT_SCALE);
      const blob = await pngBlob(canvas);
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a'); link.href = url; link.download = filename();
      document.body.append(link); link.click(); link.remove();
      setTimeout(() => URL.revokeObjectURL(url), 60000);
      status('Your 3594 × 3939 PNG is ready.');
    } catch (error) { status(error.message, true); }
    finally { $('download').disabled = false; }
  });

  $('preview').addEventListener('click', async () => {
    if (!form.reportValidity()) return;
    try { $('full-preview').src = (await renderPoster(1)).toDataURL('image/png'); $('preview-dialog').showModal(); }
    catch (error) { status(error.message, true); }
  });
  $('close-preview').addEventListener('click', () => $('preview-dialog').close());
  $('preview-dialog').addEventListener('click', event => { if (event.target === $('preview-dialog')) $('preview-dialog').close(); });

  for (const field of Object.values(fields)) field.addEventListener('input', updateText);
  for (const input of Object.values(photoControls)) input.addEventListener('input', updatePhoto);
  form.addEventListener('submit', event => event.preventDefault());
  form.addEventListener('reset', () => {
    uploadRevision++;
    // The browser resets form controls after dispatching this event.
    requestAnimationFrame(() => {
      for (const key of Object.keys(fields)) fields[key].value = defaults[key];
      if (originalPortrait) { portraitImage = originalPortrait; $('student-portrait').src = originalPortrait.src; }
      resetPhotoPosition(); updateText(); status('Original student details and portrait restored.');
    });
  });

  $('student-photo').addEventListener('change', async event => {
    const file = event.target.files[0];
    if (!file) return;
    if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) { event.target.value = ''; status('Please choose a JPG, PNG or WebP photo.', true); return; }
    const revision = ++uploadRevision;
    const url = URL.createObjectURL(file);
    try {
      status('Opening your portrait…');
      const image = await loadImage(url);
      // Convert to an in-memory data URL so the same portable image feeds both
      // CSS object-fit and Canvas export, without network or CORS dependencies.
      const canvas = makeCanvas(image.naturalWidth, image.naturalHeight);
      canvas.getContext('2d').drawImage(image, 0, 0);
      const loaded = await loadImage(canvas.toDataURL('image/png'));
      if (revision !== uploadRevision) return;
      portraitImage = loaded; $('student-portrait').src = loaded.src; resetPhotoPosition();
      status('Portrait updated. Adjust its position if needed.');
    } catch (error) { if (revision === uploadRevision) status(error.message, true); }
    finally { URL.revokeObjectURL(url); }
  });

  const windowElement = $('portrait-window');
  windowElement.addEventListener('pointerdown', event => {
    if (!ready) return;
    dragStart = { clientX: event.clientX, clientY: event.clientY, x: Number(photoControls.x.value), y: Number(photoControls.y.value) };
    windowElement.setPointerCapture(event.pointerId); windowElement.classList.add('dragging');
  });
  windowElement.addEventListener('pointermove', event => {
    if (!dragStart) return;
    const bounds = windowElement.getBoundingClientRect();
    const cover = Math.max(photoBox.w / portraitImage.naturalWidth, photoBox.h / portraitImage.naturalHeight) * Number(photoControls.zoom.value) / 100;
    const extraX = (portraitImage.naturalWidth * cover - photoBox.w) * bounds.width / photoBox.w;
    const extraY = (portraitImage.naturalHeight * cover - photoBox.h) * bounds.height / photoBox.h;
    const clamp = value => Math.max(0, Math.min(100, value));
    if (extraX > 1) photoControls.x.value = clamp(dragStart.x - (event.clientX - dragStart.clientX) / extraX * 100);
    if (extraY > 1) photoControls.y.value = clamp(dragStart.y - (event.clientY - dragStart.clientY) / extraY * 100);
    updatePhoto();
  });
  function endDrag() { dragStart = null; windowElement.classList.remove('dragging'); }
  windowElement.addEventListener('pointerup', endDrag); windowElement.addEventListener('pointercancel', endDrag);

  new ResizeObserver(fitStage).observe(stage); fitStage();
  async function initialise() {
    try {
      sourceImage = await loadImage(REFERENCE_IMAGE);
      if (sourceImage.naturalWidth !== WIDTH || sourceImage.naturalHeight !== HEIGHT) throw new Error('Reference artwork dimensions do not match the template.');
      artworkImage = await loadImage(prepareArtwork());
      for (const key of Object.keys(textBoxes)) defaultTextCrops[key] = await loadImage(cropReference(textBoxes[key]));
      originalPortrait = await loadImage(cropReference(photoBox)); portraitImage = originalPortrait;
      $('fixed-artwork').src = artworkImage.src; $('student-portrait').src = portraitImage.src;
      ready = true; updateText(); updatePhoto();
      $('download').disabled = false; $('preview').disabled = false; card.dataset.ready = 'true';
      status('Ready. Your changes appear instantly.');
    } catch (error) { status(error.message, true); }
  }
  initialise();
})();
